-- Diagnostic wrappers generated by tools/validation/instrument_lua.py; edit bodies normally.
local APRTrace = APRInstrumentation and APRInstrumentation.Wrap or function(_, fn) return fn end
local APRYield = APRInstrumentation and APRInstrumentation.Yield or coroutine.yield
local APRResume = APRInstrumentation and APRInstrumentation.Resume or coroutine.resume
local APRPCall = APRInstrumentation and APRInstrumentation.PCall or pcall
-- Turns planner segments into guidance and publishes a complete or provisional itinerary.

local Constants = APR.NavigationConstants.Navigation

local nav = APR.navigation
local Shared = APR.navigation._helpers
local ActionPending = Shared.ActionPending
local ActionUsable = Shared.ActionUsable
local ContextCurrent = Shared.ContextCurrent
local DepartureAllowed = Shared.DepartureAllowed
local Distance = Shared.Distance
local Enabled = Shared.Enabled
local HasWalkingPath = Shared.HasWalkingPath
local L = Shared.L
local MissingWalkProof = Shared.MissingWalkProof
local NavigationText = Shared.NavigationText
local PlanningRequestCurrent = Shared.PlanningRequestCurrent
local Position = Shared.Position
local ReuseWalkingCursor = Shared.ReuseWalkingCursor
local SameAccess = Shared.SameAccess
local SameLocationFields = Shared.SameLocationFields
local SpatialDistance = Shared.SpatialDistance
local TerrainRequired = Shared.TerrainRequired
local WalkingProvider = Shared.WalkingProvider

function nav:IsItineraryValid()
    if not self:IsNavigating() or not ContextCurrent(self.context) then return false end
    local copper = 0
    local provider = WalkingProvider()
    local data = APR.NavigationData
    for index = self.cursor, #self.queue do
        local step = self.queue[index]
        if step.discoverTaxiNode and APR:HasTaxiNode(step.fromNodeID) then return false end
        -- An unavailable-terrain estimate can guide, but cannot establish a
        -- measured incumbent or survive a definitive complete-search refusal.
        if step.provisionalEstimate or MissingWalkProof(step, provider) then return false end
        local departure = step.from
        if index == self.cursor then departure = Position() end
        if step.kind == "walk" and departure and data then
            if index == self.cursor and step.path and step.path.flight and not self:CanFlyHere() then return false end
            -- Explicit crossings can join two access regions. An observed
            -- player can follow their proved corridor from either side.
            if step.connectionID and HasWalkingPath(step) and data.IsSameAccessRegion then
                if index == self.cursor
                    and not data:IsSameAccessRegion(departure, step.from)
                    and not data:IsSameAccessRegion(departure, step.to) then return false end
            elseif data:CanWalk(departure, step.to) == false then
                return false
            end
        end
        if
            index == self.cursor
            and step.kind ~= "walk"
            and not step.sourceFree
            and departure
            and step.from
            and not ActionPending(step)
        then
            -- A portal's faction/quest predicates do not prove that its former
            -- departure is still reachable after an unexpected world transition.
            if departure.instanceID ~= step.from.instanceID then return false end
            if data and data.IsSameAccessRegion then
                if data:IsSameAccessRegion(departure, step.from) == false then return false end
            elseif departure.accessKey ~= step.from.accessKey or departure.floor ~= step.from.floor then
                return false
            end
        end
        if DepartureAllowed(step, departure) == false then return false end
        copper = copper + (step.copper or 0)
        if step.action and not ActionPending(step) then
            local usable, reason = ActionUsable(step.action)
            if usable == false and reason ~= "pending_data" and reason ~= "restricted" then return false end
        end
        if
            step.kind == "taxi"
            and APR.taxiData.blocked
            and APR.taxiData.blocked[tostring(step.fromNodeID) .. ":" .. tostring(step.toNodeID)]
        then
            return false
        end
    end
    local money = GetMoney and GetMoney() or 0
    if issecretvalue and issecretvalue(money) then return true end
    return copper <= money
end--[[APR_DIAG]]; nav.IsItineraryValid = APRTrace("APR-Core/features/navigation/controller/NavigationItinerary.lua:31:nav:IsItineraryValid#1", nav.IsItineraryValid)--[[/APR_DIAG]]

function nav:GetRemainingSeconds(walkSpeedFor, flight)
    local position, seconds = Position(), 0
    local speed = self:GetMovementSpeed()
    local function walkSeconds(from, to, speedFor)
        speedFor = speedFor or walkSpeedFor
        local liveSpeed = speedFor and speedFor(from, to) or speed
        if type(liveSpeed) ~= "number" or liveSpeed <= 0 or liveSpeed ~= liveSpeed or liveSpeed == math.huge then
            liveSpeed = speed
        end
        return SpatialDistance(from, to) / liveSpeed
    end--[[APR_DIAG]]; walkSeconds = APRTrace("APR-Core/features/navigation/controller/NavigationItinerary.lua:90:walkSeconds#3", walkSeconds)--[[/APR_DIAG]]
    for index = self.cursor, #self.queue do
        local step = self.queue[index]
        local duration = step.seconds or 0
        if step.kind == "verify_taxi" and not step.discoverTaxiNode then
            -- This queue stops at the master, but comparisons still cover the
            -- potential flight and the walk from its arrival to the objective.
            -- Missing estimates cannot make an incomplete trip appear free.
            duration = step.probeDestination and (duration + walkSeconds(step.probeDestination, self.destination))
                or math.huge
        end
        if step.kind == "walk" then
            local from = index == self.cursor and position or step.from
            if HasWalkingPath(step) and step.path.flight then
                if index == self.cursor then
                    -- Keep the priced climb and takeoff in candidate comparisons.
                    local yards = self:GetRemainingWalkYards()
                    local full = 0
                    for i = 2, #step.path do full = full + Distance(step.path[i - 1], step.path[i]) end
                    duration = full > 0 and step.seconds * (yards / full) or 0
                end
            elseif HasWalkingPath(step) then
                duration = 0
                local groundSpeedFor = flight and flight.groundSpeedFor
                if index == self.cursor and step.pathAimPoint then
                    duration = walkSeconds(from, step.pathAimPoint, groundSpeedFor)
                    from = step.pathAimPoint
                end
                for pathIndex = index == self.cursor and (step.pathAimIndex or step.pathCursor or 2) or 2, #step.path do
                    local point = step.path[pathIndex]
                    duration = duration + walkSeconds(from, point, groundSpeedFor)
                    from = point
                end
            else
                duration = walkSeconds(from, step.to)
            end
        elseif index == self.cursor and not step.sourceFree then
            duration = duration + walkSeconds(position, step.from)
        end
        seconds = seconds + duration
    end
    return seconds
end--[[APR_DIAG]]; nav.GetRemainingSeconds = APRTrace("APR-Core/features/navigation/controller/NavigationItinerary.lua:87:nav:GetRemainingSeconds#2", nav.GetRemainingSeconds)--[[/APR_DIAG]]

-- Convert a single world-space segment to APR's route-row coordinates. The
-- planner calls this incrementally; published rows remain separate from quests.
function nav:PrepareGuidanceStep(segment, index, generation, position)
    local source, target = segment.from, segment.to
    if not source or not target then return nil end
    local walking = segment.kind == "walk" or (segment.kind == "passage" and source.instanceID == target.instanceID)
    local point = walking and target or source
    -- Personal travel can be activated at the current position. Its planned
    -- origin remains useful to the search, but is not a waypoint to walk back to.
    local needsCoordinate = not (segment.sourceFree and segment.action)
    local label = segment.instruction
    if not label or label == "" then
        local info = target.uiMapID and C_Map and C_Map.GetMapInfo and C_Map.GetMapInfo(target.uiMapID)
        label = walking and NavigationText("RUN_WAYPOINT")
            or string.format(NavigationText("TRAVEL_TO"), info and info.name or NavigationText("UNKNOWN"))
    end
    return {
        id = generation .. ":" .. index,
        connectionID = segment.id,
        kind = segment.kind,
        from = source,
        to = target,
        path = segment.kind == "walk" and segment.path or nil,
        pathCursor = segment.kind == "walk" and segment.path and #segment.path > 1 and (segment.pathCursor or 2) or nil,
        Coord = needsCoordinate and { x = point.y, y = point.x, mapID = point.uiMapID, instanceID = point.instanceID }
            or nil,
        uiMapID = point.uiMapID,
        instanceID = point.instanceID,
        mandatory = true,
        generated = true,
        action = segment.action,
        sourceFree = segment.sourceFree == true,
        hearthstone = segment.hearthstone == true,
        canStart = segment.canStart,
        seconds = segment.seconds or 0,
        probeDestination = segment.probeDestination,
        copper = segment.copper or 0,
        arrivalZTolerance = segment.arrivalZTolerance,
        arrivalRadius = segment.arrivalRadius,
        approachOnly = segment.approachOnly,
        fromNodeID = segment.fromNodeID,
        toNodeID = segment.toNodeID,
        discoverTaxiNode = segment.discoverTaxiNode,
        departureSeen = segment.departureSeen or segment.sourceFree == true or Distance(position, source) <= 30,
        boarded = segment.boarded,
        breakAfter = segment.kind == "verify_taxi" and not segment.discoverTaxiNode,
        contextKey = segment.contextKey,
        label = label,
    }
end--[[APR_DIAG]]; nav.PrepareGuidanceStep = APRTrace("APR-Core/features/navigation/controller/NavigationItinerary.lua:133:nav:PrepareGuidanceStep#4", nav.PrepareGuidanceStep)--[[/APR_DIAG]]

-- A physically validated local corridor can guide before the world catalogue
-- finishes. It is a publication of this request, not a second planning owner.
function nav:PublishLocalPath(result, context, generation, job, inputs, unavailable, pathStatus)
    if self.worldLoading or not Enabled() or (UnitIsDeadOrGhost and UnitIsDeadOrGhost("player")) then return end
    if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
    if type(result) ~= "table" then return end
    if not unavailable and (type(result.path) ~= "table" or #result.path < 2) then return end
    if
        type(result.seconds) ~= "number"
        or result.seconds < 0
        or result.seconds ~= result.seconds
        or result.seconds == math.huge
    then
        return
    end
    local changed = self:HasPlanningInputsChanged(Position())
    if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
    if changed then
        self:RefreshStalePlanningInputs()
        return
    end
    local data = APR.NavigationData
    local service = APR.Services and APR.Services:GetStep()
    local target = self.destination
    local approachOnly = pathStatus == "partial" or result.partial == true
    if approachOnly then
        -- A bounded approach returned as ready uses the same terrain proof
        -- as a complete search. Open-ended previews require fine proof.
        if
            unavailable
            or not result.partial
            or (pathStatus ~= "ready" and result.geometryVerified ~= true)
            or not service
            or not service._mapWaypoint
        then
            return
        end
        target = result.path[#result.path]
        if not target or Distance(target, self.destination) == math.huge then return end
    end
    if data:CanWalk(self.start, target) ~= true then return end
    local row = self:PrepareGuidanceStep(
        {
            kind = "walk",
            from = self.start,
            to = target,
            path = not unavailable and result.path or nil,
            seconds = result.seconds,
        },
        1,
        generation,
        self.start
    )
    ReuseWalkingCursor(row, self.walkingPrefix)
    local _, reachable = self:AdvanceWalkingPath(row, Position(), nil, true)
    if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
    if not reachable then
        self:RefreshStalePlanningInputs()
        return
    end
    row.provisionalEstimate = unavailable or nil
    if MissingWalkProof(row, WalkingProvider()) then return end
    local training = APR.Services and APR.Services.training
    local remainingLabel
    if approachOnly then
        row.approachOnly, row.arrivalRange, row.residualYards = true, 1, Distance(target, self.destination)
        remainingLabel = APR.Services:GetLabel() .. " (" .. math.ceil(row.residualYards) .. " " .. L["YARDS"] .. ")"
        row.label = NavigationText("RUN_WAYPOINT")
            .. "\n"
            .. remainingLabel
            .. " — "
            .. NavigationText("PATH_NOT_FOUND")
    elseif service or (training and APR.Services:IsTrainingCurrent(training)) then
        row.arrivalRange, row.arrivalZTolerance = Constants.WALK_ARRIVAL_RADIUS, self.destination.z and 5 or nil
        if service then row.label = APR.Services:GetLabel() end
    end
    if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
    changed = self:HasPlanningInputsChanged(Position())
    if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
    if changed then
        self:RefreshStalePlanningInputs()
        return
    end
    self.queue, self.cursor, self.state = { row }, 1, "guiding"
    self.walkingPreview = nil
    self.walkingPrefix = nil
    self.waypointApproach = approachOnly
            and {
                endpoint = target,
                residualYards = row.residualYards,
                remainingHeight = result.remainingHeight,
                label = remainingLabel,
            }
        or nil
    self.retainedArrow, self.recomputeKeepingDirect, self._directBaselinePending = nil, nil, nil
    self.recomputeKeepingPath = true
    self.totalSeconds, self.totalCopper = result.seconds, 0
    self:Notify()
    return true
end--[[APR_DIAG]]; nav.PublishLocalPath = APRTrace("APR-Core/features/navigation/controller/NavigationItinerary.lua:183:nav:PublishLocalPath#5", nav.PublishLocalPath)--[[/APR_DIAG]]

function nav:CanReuseServiceItinerary(result, start, goal, provider)
    local segments = result.segments
    if type(segments) ~= "table" or #segments == 0 or not start or not goal then return false end
    local first, last = segments[1], segments[#segments]
    if
        Distance(start, first.from) > 0.01
        or not SameAccess(start, first.from)
        or Distance(goal, last.to) > 0.01
        or not SameAccess(goal, last.to)
    then
        return false
    end
    local departure = HasWalkingPath(first) and first.path[1] or first.from
    local arrival = HasWalkingPath(last) and last.path[#last.path] or last.to
    if start.z ~= nil and departure.z ~= nil and math.abs(start.z - departure.z) > 5 then return false end
    if goal.z ~= nil and arrival.z ~= nil and math.abs(goal.z - arrival.z) > 5 then return false end
    if GetMoney and (result.totalCopper or 0) > GetMoney() then return false end
    for _, segment in ipairs(segments) do
        if not segment.from or not segment.to then return false end
        if
            MissingWalkProof(segment, provider)
            or (
                provider
                and not provider.RequiresWalkingProof
                and segment.kind == "walk"
                and not HasWalkingPath(segment)
                and Distance(segment.from, segment.to) > 0
                and TerrainRequired(segment.from, segment.to, provider)
            )
        then
            return false
        end
        if segment.canStart and segment.canStart(segment.from, true) ~= true then return false end
        if segment.action and ActionUsable(segment.action) ~= true then return false end
        local blocked = APR.taxiData and APR.taxiData.blocked
        if
            segment.kind == "taxi"
            and blocked
            and blocked[tostring(segment.fromNodeID) .. ":" .. tostring(segment.toNodeID)]
        then
            return false
        end
    end
    return true
end--[[APR_DIAG]]; nav.CanReuseServiceItinerary = APRTrace("APR-Core/features/navigation/controller/NavigationItinerary.lua:279:nav:CanReuseServiceItinerary#6", nav.CanReuseServiceItinerary)--[[/APR_DIAG]]

function nav:GetWaypointTail(target)
    if
        not self.waypointJourney
        or not self:IsItineraryValid()
        or not self.destination
        or target.instanceID ~= self.destination.instanceID
    then
        return
    end
    local last = self.queue[#self.queue]
    local lastFixed = #self.queue - (last.kind == "walk" and 1 or 0)
    if lastFixed < self.cursor then return end
    local anchor = self.queue[lastFixed].to
    if anchor.instanceID ~= target.instanceID then return end
    local before = {}
    for index = self.cursor, lastFixed do
        before[#before + 1] = self.queue[index]
    end
    return { from = anchor, to = target, before = before, destination = true }
end--[[APR_DIAG]]; nav.GetWaypointTail = APRTrace("APR-Core/features/navigation/controller/NavigationItinerary.lua:325:nav:GetWaypointTail#7", nav.GetWaypointTail)--[[/APR_DIAG]]

function nav:Publish(result, context, generation)
    if self.worldLoading then return end
    if generation ~= self.generation or not ContextCurrent(context) then return end
    if not Enabled() or (UnitIsDeadOrGhost and UnitIsDeadOrGhost("player")) then
        self:Cancel("inactive")
        return
    end
    local job, inputs = self.search, self._routeInputs
    if job and job.serviceDeparture then
        local reusable = SameLocationFields(Position(), job.serviceDeparture, Constants.LOCATION_FIELDS)
            and self:CanReuseServiceItinerary(result, self.start, self.destination, WalkingProvider())
        if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
        if not reusable then
            self:DiscardCandidate("service_itinerary_changed")
            self:RequestUpdate()
            return
        end
    end
    local changed = inputs and self:HasPlanningInputsChanged(Position())
    if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
    if changed then
        self:RefreshStalePlanningInputs()
        return
    end
    self:CancelLocalPath()
    self.search, self._searchTimer = nil, nil
    self._directBaselinePending = nil
    result = result or {}
    local provider = WalkingProvider()
    if provider and provider.RequiresWalkingProof then
        local candidates = result.queue or result.segments or Constants.EMPTY_GUIDANCE
        local missingCoverage = #candidates == 0
            and self.start
            and self.destination
            and MissingWalkProof({ kind = "walk", from = self.start, to = self.destination }, provider)
        for _, step in ipairs(candidates) do
            if MissingWalkProof(step, provider) then
                missingCoverage = true
                break
            end
        end
        if missingCoverage then
            self.waitingData = true
            if self.lastPlanning then self.lastPlanning.status = "waiting_data" end
            self:SearchFailed(nil, true)
            return
        end
    end
    local service = APR.Services and APR.Services:GetStep()
    local servicePolicyValid = not service
        or service._mapWaypoint
        or APR.NavigationData:IsServiceItineraryAllowed(self.queue, self.cursor, result)
    if
        self.recomputeKeepingPath
        and not result.taxiDiscovery
        and not self.waypointApproach
        and not self.walkingPrefix
        and not self.travelPrefix
        and self:IsItineraryValid()
        and servicePolicyValid
    then
        if not Position() then
            self.recomputeKeepingPath = nil
            return
        end
        -- Compare both complete journeys using this search's speed model,
        -- including future outdoor/indoor walks. Stored segment durations may
        -- have been measured while flying and cannot compete with a fresh plan.
        local request = job and job.request
        local remaining = self:GetRemainingSeconds(request and request.walkSpeedFor, request and request.flight)
        local candidate = result.totalSeconds or math.huge
        -- Keep exact ties stable, but accept every meaningful improvement.
        -- A fixed percentage/floor can retain a slower itinerary indefinitely.
        local requiredGain = 0.001
        local committed = ActionPending(self:GetActiveStep())
        self.lastComparison = {
            remainingSeconds = remaining,
            candidateSeconds = candidate,
            requiredGain = requiredGain,
            retained = committed or remaining - candidate <= requiredGain,
        }
        if self.lastComparison.retained then
            self.recomputeKeepingPath = nil
            return
        end
    end
    self.recomputeKeepingPath = nil
    local queue = result.queue
    if not queue then
        -- Publish also accepts small routes supplied by another APR component.
        -- The normal planner prepares these rows within its frame budget.
        queue = {}
        local position = Position()
        for index, segment in ipairs(result.segments or {}) do
            local entry = self:PrepareGuidanceStep(segment, index, generation, position)
            if entry then queue[#queue + 1] = entry end
        end
    end
    if not PlanningRequestCurrent(self, context, generation, nil, inputs) then return end
    local observed, cursor = Position(), 1
    if result.waypointLeg then
        queue, cursor, result.totalSeconds, result.totalCopper =
            self:JoinWaypointLeg(queue, result.waypointLeg, observed)
        if not queue then
            self:Cancel("replan")
            self:ForceRefresh("waypoint_leg_unavailable")
            self:RequestUpdate()
            return
        end
    else
        ReuseWalkingCursor(queue[1], self.walkingPrefix or (self.travelPrefix and self:GetActiveStep()))
        local _, reachable = self:AdvanceWalkingPath(queue[1], observed, nil, true)
        changed = not reachable
            or (
                inputs
                and self:HasPlanningInputsChanged(
                    observed,
                    provider and provider.CanFollowWalkingSegment and HasWalkingPath(queue[1])
                )
            )
    end
    if not PlanningRequestCurrent(self, context, generation, nil, inputs) then return end
    if changed then
        self:RefreshStalePlanningInputs()
        return
    end
    local service = APR.Services and APR.Services:GetStep()
    local approach
    if service then
        local final = queue[#queue]
        local restored = result.waypointLeg and result.waypointLeg.restored
        if restored and restored.pending and final then
            service.waypointLeg = { from = final.to, to = service.target, before = queue, destination = true }
            self.dirty = true
            self:RequestUpdate()
            return
        end
        if final and final.approachOnly and service._mapWaypoint then
            final.arrivalRange, final.residualYards = 1, Distance(final.to, service.target)
            local label = APR.Services:GetLabel() .. " (" .. math.ceil(final.residualYards) .. " " .. L["YARDS"] .. ")"
            final.label = NavigationText("RUN_WAYPOINT") .. "\n" .. label .. " — " .. NavigationText("PATH_NOT_FOUND")
            approach = { endpoint = final.to, residualYards = final.residualYards, label = label }
        elseif not final or Distance(final.to, service.target) > 0.01 then
            -- Only the library may supply the journey to the selected service.
            -- An incomplete result must never acquire an invented walking leg.
            if self.waypointApproach then
                self:SearchFailed()
                return
            end
            self:MarkRouteReady()
            return
        else
            if final.kind ~= "walk" then
                queue[#queue + 1] = self:PrepareGuidanceStep(
                    { kind = "walk", from = service.target, to = service.target, instruction = APR.Services:GetLabel() },
                    #queue + 1,
                    generation,
                    Position()
                )
            end
            queue[#queue].arrivalRange, queue[#queue].arrivalZTolerance =
                Constants.WALK_ARRIVAL_RADIUS, service.target.z and 5 or nil
            queue[#queue].label = APR.Services:GetLabel()
        end
    end
    local training = APR.Services and APR.Services.training
    if training and training.target and APR.Services:IsTrainingCurrent(training) then
        local final = queue[#queue]
        if final then
            final.arrivalRange, final.arrivalZTolerance = 5, training.target.z and 5 or nil
        end
    end
    if
        #queue <= 1
        and (not queue[1] or queue[1].kind == "walk")
        and self.zoneReady
        and not HasWalkingPath(queue[1])
    then
        self:MarkRouteReady()
        return
    end
    self.recomputeKeepingDirect = nil
    self.retainedArrow = nil
    self.queue, self.cursor = queue, cursor
    self.walkingPrefix, self.travelPrefix = nil, nil
    self.waypointPendingLeg, self.waypointPreview = nil, nil
    if service and service._mapWaypoint then
        self.waypointJourney = result.waypointLeg ~= nil or self.start.instanceID ~= self.destination.instanceID
    end
    self.waypointApproach = approach
    self._transitionArrival, self._resumeAfterTransition, self._transitionProbe = nil, nil, nil
    self.state = #queue > 0 and "guiding" or "no_path"
    self.totalSeconds, self.totalCopper = result and result.totalSeconds, result and result.totalCopper
    self._routedStepContext = context
    self:Notify()
    if
        job
        and job.startedAt
        and not job.firstGuidanceMilliseconds
        and HasWalkingPath(queue[1])
        and generation == self.generation
        and self.queue == queue
        and self.lastPlanning
        and debugprofilestop
    then
        self.lastPlanning.firstGuidanceMilliseconds = debugprofilestop() - job.startedAt
        if APR.RecordPerformanceDuration then
            APR:RecordPerformanceDuration(
                "NavigationFirstValidatedGuidance",
                self.lastPlanning.firstGuidanceMilliseconds
            )
        end
    end
    self:PollArrival()
end--[[APR_DIAG]]; nav.Publish = APRTrace("APR-Core/features/navigation/controller/NavigationItinerary.lua:346:nav:Publish#8", nav.Publish)--[[/APR_DIAG]]
